const data = $json;

const execution = data.execution ?? {};
const trigger = data.trigger ?? {};
const workflow = data.workflow ?? {};

const triggerError = trigger.error ?? {};
const executionError = execution.error ?? {};

// Execution ID may legitimately be missing if the failure
// happened in the trigger before a workflow execution existed.
const executionId =
  execution.id !== undefined && execution.id !== null
    ? String(execution.id).trim()
    : '';

// Prefer the normal execution error message.
// Fall back safely for trigger-level failures.
const errorMessage =
  executionError.message ||
  triggerError.message ||
  triggerError.cause?.message ||
  'Unknown workflow error';

// Preserve the node that failed whenever n8n provides it.
const failedNode =
  execution.lastNodeExecuted ||
  triggerError.node?.name ||
  '';

// Preserve error name when available.
const errorName =
  executionError.name ||
  triggerError.name ||
  '';

// Keep workflow identity for debugging and safety.
const workflowId =
  workflow.id !== undefined && workflow.id !== null
    ? String(workflow.id).trim()
    : '';

const workflowName =
  typeof workflow.name === 'string'
    ? workflow.name
    : '';

// Identify whether the error came from a normal execution
// or directly from a trigger-level failure.
const errorSource =
  trigger.error
    ? 'TRIGGER'
    : execution.error
      ? 'EXECUTION'
      : 'UNKNOWN';

// Select the actual structured error object for deeper details.
const structuredError =
  executionError &&
  typeof executionError === 'object' &&
  Object.keys(executionError).length > 0
    ? executionError
    : triggerError &&
      typeof triggerError === 'object' &&
      Object.keys(triggerError).length > 0
      ? triggerError
      : {};

// Helper: return the first meaningful value.
const firstNonEmpty = (...values) => {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return '';
};

// Optional longer error description.
const errorDescription = String(
  firstNonEmpty(
    structuredError.description,
    ''
  )
);

// Extract HTTP status when n8n/provider supplies one.
const httpStatusRaw = firstNonEmpty(
  structuredError.httpCode,
  structuredError.statusCode,
  structuredError.response?.status,
  structuredError.cause?.statusCode,
  structuredError.cause?.response?.status
);

const parsedHttpStatus =
  httpStatusRaw === ''
    ? NaN
    : Number.parseInt(String(httpStatusRaw), 10);

const httpStatus =
  Number.isFinite(parsedHttpStatus)
    ? parsedHttpStatus
    : null;

// Extract a structured provider/API error code when available.
const providerErrorCode = String(
  firstNonEmpty(
    structuredError.errorCode,
    structuredError.code,
    structuredError.response?.data?.error?.status,
    structuredError.response?.data?.error?.code,
    structuredError.cause?.code,
    ''
  )
).trim();

return {
  json: {
    execution_id: executionId,

    execution_url:
      typeof execution.url === 'string'
        ? execution.url
        : '',

    retry_of:
      execution.retryOf !== undefined && execution.retryOf !== null
        ? String(execution.retryOf)
        : '',

    execution_mode:
      execution.mode ||
      trigger.mode ||
      '',

    failed_node: failedNode,

    workflow_id: workflowId,
    workflow_name: workflowName,

    error_name: errorName,
    error_message: String(errorMessage),

    error_description: errorDescription,
    http_status: httpStatus,
    provider_error_code: providerErrorCode,

    error_source: errorSource,

    // Safety flag for the next step.
    // We will only attempt lead lookup when this is true.
    can_lookup_by_execution_id: executionId.length > 0
  }
};

const failedNode = String($json.failed_node || '').trim();

const beforeGmailNodes = new Set([
  'On form submission',
  'Normalize Input',
  'Input Validation',
  'Log INVALID_INPUT',
  'Duplicate Check - New Lead',
  'Save PROCESSING State',
  'AI Lead Extraction',
  'Validate AI JSON',
  'Mark AI_OUTPUT_INVALID',
  'Queue AI_OUTPUT_INVALID Review',
  'Business Rules - Lead Scoring',
  'Route Lead Status',
  'Mark REVIEW',
  'Queue LEAD_REVIEW',
  'AI Email Draft',
  'Email Guardrails',
  'Mark EMAIL_DRAFT_INVALID',
  'Queue EMAIL_DRAFT_INVALID Review',
  'Mark EMAIL_READY',
]);

const atGmailNodes = new Set([
  'Gmail Send',
]);

const afterGmailNodes = new Set([
  'Update Final State',
  'Update AI Lead CRM',
]);

let failureStage = 'UNKNOWN';

if (beforeGmailNodes.has(failedNode)) {
  failureStage = 'BEFORE_GMAIL';
} else if (atGmailNodes.has(failedNode)) {
  failureStage = 'AT_GMAIL';
} else if (afterGmailNodes.has(failedNode)) {
  failureStage = 'AFTER_GMAIL';
}

return {
  json: {
    ...$json,
    failure_stage: failureStage,
    classification_basis: failedNode || 'No failed node provided',
  },
};

const error =
  $('Normalize Error Details').first().json;

const httpStatus =
  error.http_status === null ||
  error.http_status === undefined
    ? null
    : Number(error.http_status);

const providerCode =
  String(error.provider_error_code || '')
    .trim()
    .toUpperCase();

const provenNotAcceptedHttpStatuses = new Set([
  400,
  401,
  403,
  404,
  405,
  413,
  415,
  422,
  429,
]);

const provenNotAcceptedProviderCodes = new Set([
  'INVALID_GRANT',
  'INVALID_REQUEST',
  'UNAUTHENTICATED',
  'UNAUTHORIZED',
  'PERMISSION_DENIED',
  'FORBIDDEN',
]);

let gmailOutcome = 'SEND_UNCERTAIN';
let gmailOutcomeBasis =
  'No structured proof that Gmail rejected the send';

if (
  Number.isInteger(httpStatus) &&
  provenNotAcceptedHttpStatuses.has(httpStatus)
) {
  gmailOutcome = 'SEND_FAILED';
  gmailOutcomeBasis =
    `Structured HTTP rejection: ${httpStatus}`;
} else if (
  providerCode &&
  provenNotAcceptedProviderCodes.has(providerCode)
) {
  gmailOutcome = 'SEND_FAILED';
  gmailOutcomeBasis =
    `Structured provider rejection: ${providerCode}`;
}

return {
  json: {
    ...$json,
    gmail_outcome: gmailOutcome,
    gmail_outcome_basis: gmailOutcomeBasis,
  },
};
